import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import java.util.*;

public final class StarterDeck100BlisseyTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    public static void main(String[] args){for(String mode:List.of("MANUAL","HAND_EFFECT","DECK","DISCARD","OPPONENT_HAND","BENCH"))cure(mode);for(boolean take:List.of(false,true))blast(take);blocked();System.out.println("StarterDeck100BlisseyTest passed: own-hand/manual/effect triggers, source-zone and owner exclusions, own-source identity, optional post-damage Energy, units, invalid-host discard and prevented damage gate");}
    static void cure(String mode){var m=StarterDeck100PokemonTest.game(334,1,"sm1_en_136");var source=m.activePokemonView(A).pokemonId();m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);m.applySpecialConditionByEffect(A,A,SpecialCondition.BURNED);m.applySpecialConditionByEffect(A,A,SpecialCondition.CONFUSED);var e=StarterDeck100PokemonTest.hand(m,"sm1_en_136");if(mode.equals("MANUAL"))m.attachEnergy(A,e.instanceId(),source);if(mode.equals("HAND_EFFECT"))m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,e.instanceId(),A,source);if(mode.equals("DECK"))StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_grass_energy",source);if(mode.equals("DISCARD")){m.discardHandCardsByEffect(A,A,List.of(e.instanceId()));m.attachEnergyByEffect(A,A,EffectSourceZone.DISCARD,e.instanceId(),A,source);}if(mode.equals("OPPONENT_HAND")){var other=m.privateView(B).hand().stream().filter(c->m.cardDefinition(c.definitionId()).basicEnergy()).findFirst().orElseThrow();m.attachEnergyByEffect(A,B,EffectSourceZone.HAND,other.instanceId(),A,source);}if(mode.equals("BENCH"))m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,e.instanceId(),A,m.benchPokemonView(A).getFirst().pokemonId());boolean cured=mode.equals("MANUAL")||mode.equals("HAND_EFFECT");check(m.activePokemonView(A).conditions().isEmpty()==cured,"Natural Cure wrong source/zone: "+mode);check(m.triggerOrderPrompt()==null,"mandatory single cure left a prompt");}
    static void blast(boolean take){var m=StarterDeck100PokemonTest.game(334,1,"sm1_en_136",id(412));var cards=List.of(StarterDeck100PokemonTest.hand(m,"sd100_cn_grass_energy"),StarterDeck100PokemonTest.hand(m,"sm1_en_136"),StarterDeck100PokemonTest.hand(m,id(412)));m.discardHandCardsByEffect(A,A,cards.stream().map(c->c.instanceId()).toList());m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==40,"Blissful Blast initial damage");var p=m.effectCardPrompt(A);check(p.candidates().containsAll(cards),"Single Strike Energy was wrongly excluded from effect attachment");m.submitEffectCards(A,p.resolutionId(),p.step(),take?cards.stream().map(c->c.instanceId()).toList():List.of());check(m.activePokemonView(A).attachedEnergyIds().size()==(take?3:1),"post-attack Energy count");check(m.privateView(A).discard().contains(cards.get(2)),"invalid-host Energy did not discard");check(m.activePokemonView(A).conditions().contains(SpecialCondition.POISONED)&&m.activePokemonView(A).damage()==10,"discard attachment cured poison");check(m.lastAttack().finalDamage()==40,"new Energy changed damage already dealt");m.endTurn(B);m.attack(A,"blissful-blast");if(m.hasPendingCardSelection())StarterDeck100PokemonTest.select(m,0);check(m.lastAttack().finalDamage()==(take?130:40),"Blissful Blast counted Energy cards instead of units");}
    static void blocked(){var m=StarterDeck100PokemonTest.game(334,123);var e=StarterDeck100PokemonTest.hand(m,"sd100_cn_grass_energy");m.discardHandCardsByEffect(A,A,List.of(e.instanceId()));m.endTurn(A);StarterDeck100GuardTest.attackOpponent(m,123,1);StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==0&&!m.hasPendingCardSelection()&&m.privateView(A).discard().contains(e),"prevented damage still attached Energy");}
}
